import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            long res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -res : res;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int P = sc.nextInt();
        if (P <= 0) {
            out.flush();
            return;
        }

        for (int i = 0; i < P; i++) {
            long L = sc.nextLong();
            long A = sc.nextLong();
            long B = sc.nextLong();

            long low = 0;
            long high = Math.min(B - A, 5000000L);
            long bestM = 0;

            while (low <= high) {
                long mid = (low + high) >>> 1;
                long sum = mid * A + (mid * (mid - 1)) / 2;
                if (sum < L) {
                    bestM = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            out.println(bestM + 1);
        }

        out.flush();
    }
}
